sys_script_fix.script:
(function() {
    var table = 'x_1831875_amp2_0_property_table'; //update if needed
    var field = 'prop_common_name';

    var gr = new GlideRecord(table);
    gr.addQuery(field, 'STARTSWITH', 'NMFS');
    gr.query();

    var count = 0;

    while (gr.next()) {
        var original = gr.getValue(field);

        //remove NMFS + dash + whitespace
        var cleaned = original.replace(/^NMFS\s*[--]?\s*/i, '').trim();

        if (cleaned !== original) {
            gr.setValue(field, cleaned);
            gr.update();
            count++;

            gs.info('[NMFS CLEANUP][PROPERTY]' + original + ' -> ' + cleaned);
        }

    }
    gs.info('NMFS cleanup completed for Properties. Records updated: ' + count);

})();
